{
"type": 26,
"mute_notifications": false,
"reverse_data_order": false,
"led_mode": 0 // 0 - Не мигать, //1 - Красным, //2 - Зеленым
}

{
    "all_server_certs": false, //Удалить все сертификаты (именно серверные)
	"webhook_cert": false //Удалить сертификат для вебхука
}

{
	"enable": true, //Включить BLE 
	"mark": {
		"button": {
			"enable": false //Включить срабатывание по кнопке BLE метки 
		},
		"distance": {
			"enable": false, //Включить срабатывание по дистанции BLE метки
			"triggered_rssi": -90 //Дистанция срабатывания. Принимает значения от -116 до -36 с шагом 1. 
		}
	},
	"app": {
		"button": {
			"enable": true //Включить срабатывание по кнопке приложения. 
		},
		"distance": {
			"enable": true, //Включить срабатывание по дистанции приложения.
			"triggered_rssi": -96 //Дистанция срабатывания. Принимает значения от -116 до -36 с шагом 1.
		}
	}
}
